1	import invariant from '../util/invariant';
2	
3	import type { AssertionParams, GradingResult } from '../types/index';
4	
5	export const handleContains = ({
6	  assertion,
7	  renderedValue,
8	  valueFromScript,
9	  outputString,
10	  inverse,
11	}: AssertionParams): GradingResult => {
12	  const value = valueFromScript ?? renderedValue;
13	  invariant(value, '"contains" assertion type must have a string or number value');
14	  invariant(
15	    typeof value === 'string' || typeof value === 'number',
16	    '"contains" assertion type must have a string or number value',
17	  );
18	  const pass = outputString.includes(String(value)) !== inverse;
19	  return {
20	    pass,
21	    score: pass ? 1 : 0,
22	    reason: pass
23	      ? 'Assertion passed'
24	      : `Expected output to ${inverse ? 'not ' : ''}contain "${value}"`,
25	    assertion,
26	  };
27	};
