29	export const handleIContains = ({
30	  assertion,
31	  renderedValue,
32	  valueFromScript,
33	  outputString,
34	  inverse,
35	}: AssertionParams): GradingResult => {
36	  const value = valueFromScript ?? renderedValue;
37	  invariant(value, '"icontains" assertion type must have a string or number value');
38	  invariant(
39	    typeof value === 'string' || typeof value === 'number',
40	    '"icontains" assertion type must have a string or number value',
41	  );
42	  const pass = outputString.toLowerCase().includes(String(value).toLowerCase()) !== inverse;
43	  return {
44	    pass,
45	    score: pass ? 1 : 0,
46	    reason: pass
47	      ? 'Assertion passed'
48	      : `Expected output to ${inverse ? 'not ' : ''}contain "${value}"`,
49	    assertion,
50	  };
51	};
