53	export const handleContainsAny = ({
54	  assertion,
55	  renderedValue,
56	  valueFromScript,
57	  outputString,
58	  inverse,
59	}: AssertionParams): GradingResult => {
60	  let value = valueFromScript ?? renderedValue;
61	  invariant(value, '"contains-any" assertion type must have a value');
62	  if (typeof value === 'string') {
63	    // Handle quoted values and escaped commas
64	    value =
65	      value.match(/(".*?"|[^,]+)(?=\s*,|\s*$)/g)?.map((v) => v.trim().replace(/^"|"$/g, '')) ?? [];
66	  }
67	  invariant(Array.isArray(value), '"contains-any" assertion type must have an array value');
68	  const pass = value.some((v) => outputString.includes(String(v))) !== inverse;
69	  return {
70	    pass,
71	    score: pass ? 1 : 0,
72	    reason: pass
73	      ? 'Assertion passed'
74	      : `Expected output to ${inverse ? 'not ' : ''}contain one of "${value.join(', ')}"`,
75	    assertion,
76	  };
77	};
