79	export const handleIContainsAny = ({
80	  assertion,
81	  renderedValue,
82	  valueFromScript,
83	  outputString,
84	  inverse,
85	}: AssertionParams): GradingResult => {
86	  let value = valueFromScript ?? renderedValue;
87	  invariant(value, '"icontains-any" assertion type must have a value');
88	  if (typeof value === 'string') {
89	    value = value.split(',').map((v) => v.trim());
90	  }
91	  invariant(Array.isArray(value), '"icontains-any" assertion type must have an array value');
92	  const pass =
93	    value.some((v) => outputString.toLowerCase().includes(String(v).toLowerCase())) !== inverse;
94	  return {
95	    pass,
96	    score: pass ? 1 : 0,
97	    reason: pass
98	      ? 'Assertion passed'
99	      : `Expected output to ${inverse ? 'not ' : ''}contain one of "${value.join(', ')}"`,
100	    assertion,
101	  };
102	};
