104	export const handleContainsAll = ({
105	  assertion,
106	  renderedValue,
107	  valueFromScript,
108	  outputString,
109	  inverse,
110	}: AssertionParams): GradingResult => {
111	  let value = valueFromScript ?? renderedValue;
112	  invariant(value, '"contains-all" assertion type must have a value');
113	  if (typeof value === 'string') {
114	    value = value.split(',').map((v) => v.trim());
115	  }
116	  invariant(Array.isArray(value), '"contains-all" assertion type must have an array value');
117	  const missingStrings = value.filter((v) => !outputString.includes(String(v)));
118	  const pass = (missingStrings.length === 0) !== inverse;
119	  return {
120	    pass,
121	    score: pass ? 1 : 0,
122	    reason: pass
123	      ? 'Assertion passed'
124	      : `Expected output to ${inverse ? 'not ' : ''}contain all of [${value.join(', ')}]. Missing: [${missingStrings.join(', ')}]`,
125	    assertion,
126	  };
127	};
